using RemoteAdmin.Shared;
namespace RemoteAdmin.Server;
public sealed partial class MainWindow {
 sealed class SettingsWindow : Form {
  public SettingsWindow(MainWindow owner){
   Classic.Dialog(this,"Настройки RemoteAdmin Server",new Size(640,440));
   var buttons=Classic.Buttons();var cancel=Classic.Button("Отмена",(_,_)=>DialogResult=DialogResult.Cancel);var ok=Classic.Button("OK",(_,_)=>{});buttons.Controls.Add(cancel);buttons.Controls.Add(ok);AcceptButton=ok;CancelButton=cancel;
   var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(10)};split.ColumnStyles.Add(new(SizeType.Absolute,190));split.ColumnStyles.Add(new(SizeType.Percent,100));split.RowStyles.Add(new(SizeType.Percent,100));var tree=new TreeView{Dock=DockStyle.Fill,HideSelection=false,ShowLines=false,ShowRootLines=false,ShowPlusMinus=false,BorderStyle=BorderStyle.FixedSingle};foreach(var title in new[]{"Общие настройки","Безопасность TLS","Журнал","Общая папка"})tree.Nodes.Add(title);split.Controls.Add(tree,0,0);var pages=new Panel{Dock=DockStyle.Fill,Padding=new Padding(12,0,0,0)};split.Controls.Add(pages,1,0);
   var general=new Panel{Dock=DockStyle.Fill};var stack=Classic.Stack();var network=Classic.Group("Порт подключения");network.AutoSize=true;var networkStack=Classic.Stack();var defaultPort=new CheckBox{Text="По умолчанию",AutoSize=true,Checked=owner.accounts.Settings.Port==4899};var value=new NumericUpDown{Minimum=1024,Maximum=65535,Value=owner.accounts.Settings.Port,Width=120,Enabled=!defaultPort.Checked};defaultPort.CheckedChanged+=(_,_)=>{value.Enabled=!defaultPort.Checked;if(defaultPort.Checked)value.Value=4899;};Classic.Add(networkStack,defaultPort);Classic.Add(networkStack,value);network.Controls.Add(networkStack);Classic.Add(stack,network);
   var showTray=new CheckBox{Text="Показывать значок в области уведомлений",AutoSize=true,Checked=owner.desktopOptions.ShowTray};Classic.Add(stack,showTray);
   var confirmation=Classic.Group("Подтверждение подключений");confirmation.AutoSize=true;var confirmationText=Classic.Label("Учётная запись: подтверждение не требуется.\nРазовая техподдержка: подтверждение обязательно.\nПрава назначаются в окне «Права доступа…».");confirmation.Controls.Add(confirmationText);Classic.Add(stack,confirmation);general.Controls.Add(stack);
   var tls=Classic.Stack();tls.Dock=DockStyle.Fill;Classic.Add(tls,Classic.Label("SHA-256 сертификата этого сервера:"));var fingerprintBox=new TextBox{Text=owner.fingerprint.Text,ReadOnly=true,Multiline=true,Height=75,Dock=DockStyle.Top,Font=new Font("Consolas",10)};Classic.Add(tls,fingerprintBox);Classic.Add(tls,Classic.Button("Копировать ключ",(_,_)=>Clipboard.SetText(fingerprintBox.Text),150));Classic.Add(tls,Classic.Label("Первый вход требует сверки ключа на клиенте.\nПри следующих входах ключ проверяется автоматически.\nЭто проверка сервера, а не подтверждение доступа."));
   var journal=Classic.Stack();journal.Dock=DockStyle.Fill;Classic.Add(journal,Classic.Label("Аудит входов и файловых операций включён.\nДиагностика не содержит паролей или команд ввода."));Classic.Add(journal,Classic.Field("Каталог журнала:",new TextBox{Text=owner.folder,ReadOnly=true}));Classic.Add(journal,Classic.Button("Открыть папку",(_,_)=>owner.OpenFolder(owner.folder),150));
   var shared=Classic.Stack();shared.Dock=DockStyle.Fill;Classic.Add(shared,Classic.Label("Разрешённая папка передачи файлов:"));Classic.Add(shared,new TextBox{Text=owner.share,ReadOnly=true,Multiline=true,Height=65});Classic.Add(shared,Classic.Label("Доступ к другим папкам через файловый API запрещён.\nПраво передачи файлов назначается пользователю."));Classic.Add(shared,Classic.Button("Открыть папку",(_,_)=>owner.OpenFolder(owner.share),150));
   Control[] all=[general,tls,journal,shared];foreach(var page in all){page.Visible=false;pages.Controls.Add(page);}tree.AfterSelect+=(_,e)=>{for(int i=0;i<all.Length;i++)all[i].Visible=i==e.Node!.Index;all[e.Node!.Index].BringToFront();};tree.SelectedNode=tree.Nodes[0];Controls.Add(split);Controls.Add(buttons);
   ok.Click+=(_,_)=>{try{int newPort=defaultPort.Checked?4899:(int)value.Value;bool restart=owner.running!=null&&newPort!=owner.accounts.Settings.Port;owner.accounts.SaveSettings(newPort,owner.accounts.Settings.Authentication,owner.accounts.Settings.SupportRights);ServerDesktop.Save(owner.folder,new DesktopOptions(showTray.Checked));owner.desktopOptions=new(showTray.Checked);owner.tray.Visible=showTray.Checked;if(restart)owner.Stop();owner.port.Value=newPort;if(restart)owner.Start();owner.session?.Cancel();LocalData.Audit(owner.folder,"settings.changed","","success");owner.UpdateState();DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(this,e.Message,"Настройки не сохранены");}};
  }
 }
 sealed class SupportWindow : Form {
  public SupportWindow(MainWindow owner){
   Classic.Dialog(this,"Разовая техподдержка",new Size(500,390));var content=Classic.Stack();content.Dock=DockStyle.Fill;content.Padding=new Padding(14);Classic.Add(content,Classic.Label("Этот режим работает только при разрешённых приглашениях.\nКод действует 5 минут; каждый вход требует вашего согласия."));
   var address=new TextBox{Text=LocalAddress()};var copyCode=new TextBox{Text=owner.pairing,ReadOnly=true};Classic.Add(content,Classic.Field("Адрес компьютера, доступный оператору:",address));Classic.Add(content,Classic.Field("Одноразовый код:",copyCode));
   var rights=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};var checks=new Dictionary<Permissions,CheckBox>();foreach(var flag in new[]{Permissions.Control,Permissions.Files,Permissions.Clipboard}){var check=new CheckBox{Text=Ui.Rights(flag),AutoSize=true,Checked=owner.accounts.Settings.SupportRights.HasFlag(flag)};checks[flag]=check;rights.Controls.Add(check);}Classic.Add(content,rights);
   Classic.Add(content,Classic.Button("Обновить код",(_,_)=>{owner.NewCode();copyCode.Text=owner.pairing;},150));Classic.Add(content,Classic.Button("Копировать приглашение",(_,_)=>{if(!owner.accounts.AllowsInvitations){MessageBox.Show(this,"Разрешите разовую помощь в «Права доступа…».");return;}if(owner.running==null){MessageBox.Show(this,"Сначала включите доступ на сервере.");return;}if(owner.pairing.Length==0||DateTimeOffset.UtcNow>=owner.codeExpires)owner.NewCode();var flags=Permissions.View|Permissions.Chat;foreach(var pair in checks)if(pair.Value.Checked)flags|=pair.Key;owner.accounts.SaveSettings(owner.accounts.Settings.Port,owner.accounts.Settings.Authentication,flags);copyCode.Text=owner.pairing;Clipboard.SetText(PairingLink.Create(address.Text.Trim(),owner.accounts.Settings.Port,owner.fingerprint.Text,owner.pairing));},210));
   Classic.Add(content,Classic.Label("Изменение прав применяется при создании следующего приглашения."));var buttons=Classic.Buttons();buttons.Controls.Add(Classic.Button("Закрыть",(_,_)=>Close()));Controls.Add(content);Controls.Add(buttons);
  }
 }
}

internal sealed class SecurityWindow : Form {
 public SecurityWindow(ServerAccounts store,Action changed){
  Classic.Dialog(this,"Режим безопасности RemoteAdmin Server",new Size(460,305));var group=Classic.Group("Система безопасности");group.Dock=DockStyle.Top;group.Height=233;
  var stack=Classic.Stack();var accounts=new RadioButton{Text="Учётные записи RemoteAdmin",AutoSize=true,Checked=store.AllowsAccounts};var invitation=new RadioButton{Text="Только одноразовые приглашения",AutoSize=true,Checked=!store.AllowsAccounts&&!store.AllowsWindows};Classic.Add(stack,accounts);Classic.Add(stack,invitation);
  var windows=new RadioButton{Text="Windows NT / AD (SSPI)",Checked=store.AllowsWindows,AutoSize=true};Classic.Add(stack,windows);var permissions=Classic.Button("Права доступа…",(_,_)=>{if(windows.Checked){using var dialog=new WindowsRightsWindow(store,changed);dialog.ShowDialog(this);}else{using var dialog=new AccountsWindow(store,changed);dialog.ShowDialog(this);}},160);Classic.Add(stack,permissions);var support=new CheckBox{Text="Также разрешить разовую техподдержку",Checked=store.AllowsInvitations&&(store.AllowsAccounts||store.AllowsWindows),AutoSize=true};Classic.Add(stack,support);Classic.Add(stack,Classic.Label("Логин и пароль — без дополнительного согласия.\nПриглашение — с обязательным согласием пользователя."));group.Controls.Add(stack);
  void UpdateControls(){permissions.Enabled=accounts.Checked||windows.Checked;support.Enabled=permissions.Enabled;}accounts.CheckedChanged+=(_,_)=>UpdateControls();windows.CheckedChanged+=(_,_)=>UpdateControls();UpdateControls();var buttons=Classic.Buttons();var cancel=Classic.Button("Отмена",(_,_)=>DialogResult=DialogResult.Cancel);var ok=Classic.Button("OK",(_,_)=>{try{var mode=windows.Checked?(support.Checked?AuthenticationMode.WindowsAndInvitation:AuthenticationMode.Windows):accounts.Checked?(support.Checked?AuthenticationMode.Both:AuthenticationMode.Accounts):AuthenticationMode.Invitation;store.SaveSettings(store.Settings.Port,mode,store.Settings.SupportRights);changed();DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(this,e.Message,"Не удалось сохранить настройки");}});buttons.Controls.Add(cancel);buttons.Controls.Add(ok);Controls.Add(group);Controls.Add(buttons);AcceptButton=ok;CancelButton=cancel;
 }
}
